namespace ComfyNetworkSense.Tests;
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using Newtonsoft.Json;
using ComfyQuestContracts;
using Xunit;

public sealed class ExperienceContractTests {
  [Fact] public void EasySignalsNormalizeWithoutPersistingPrivatePayloads(){var at=DateTimeOffset.UnixEpoch;var said=EasyEventContract.ChatSent("Normal","private words",at);Assert.Equal("chat_sent",said.Name);Assert.Equal("normal",said.Target);Assert.Null(said.Fields);Assert.DoesNotContain("private words",JsonConvert.SerializeObject(said));var shout=EasyEventContract.ChatSent("Shout","also private",at);Assert.Equal("shout",shout.Target);var drop=EasyEventContract.ItemDropped("Wood(Clone)",2,at);Assert.Equal("item_dropped",drop.Name);Assert.Equal("Wood",drop.Target);Assert.Equal("item_picked_up",EasyEventContract.ItemPickedUp("Stone(Clone)",at).Name);Assert.Equal("Stone",EasyEventContract.ItemPickedUp("Stone(Clone)",at).Target);Assert.Equal("item_equipped",EasyEventContract.ItemEquipped("Hammer(Clone)",at).Name);Assert.Equal("item_consumed",EasyEventContract.ItemConsumed("CookedMeat(Clone)",at).Name);var heal=EasyEventContract.CharacterHealed(0.5f,at);Assert.Equal("character_healed",heal.Name);Assert.Equal("you",heal.Target);Assert.Null(EasyEventContract.ChatSent("Whisper","no",at));Assert.Null(EasyEventContract.ItemDropped("Wood",0,at));Assert.Null(EasyEventContract.ItemPickedUp(null,at));Assert.Null(EasyEventContract.CharacterHealed(0f,at));}
  [Fact] public void EasySignalsSupportWildcardStudioTriggers(){var events=new[]{EasyEventContract.ItemDropped("Stone",1,DateTimeOffset.UnixEpoch),EasyEventContract.CharacterHealed(1f,DateTimeOffset.UnixEpoch)};Assert.True(TriggerEvaluator.Matches(new TriggerExpression{Op="EVENT",Event="item_dropped"},events));Assert.True(TriggerEvaluator.Matches(new TriggerExpression{Op="EVENT",Event="character_healed"},events));}
  [Fact] public void CoreLocalActionsNormalizeOnlyCatalogPayloads(){var at=DateTimeOffset.UnixEpoch;Assert.Equal("piece_chest_wood",CoreActionEventContract.ContainerEmptied("piece_chest_wood(Clone)",at).Target);Assert.Equal("AxeBronze",CoreActionEventContract.ItemUnequipped(" AxeBronze(Clone) ",at).Target);Assert.Equal("wood_wall",CoreActionEventContract.PieceDestroyed("wood_wall(Clone)",at).Target);Assert.Equal("piece",CoreActionEventContract.PieceRemoved(at).Target);Assert.Equal("wood_wall",CoreActionEventContract.PieceRepaired("wood_wall",at).Target);Assert.Null(CoreActionEventContract.PlayerTeleported(at).Target);Assert.Null(CoreActionEventContract.ContainerEmptied(" ",at));Assert.Null(CoreActionEventContract.ItemUnequipped(null,at));}
  [Fact] public void CoreLocalActionProofRejectsDeniedPartialStaleRemoteAndNoOpPaths(){Assert.True(CoreActionProof.ContainerEmptied(true,true,3,0,0.5));Assert.False(CoreActionProof.ContainerEmptied(true,false,3,0,0.5));Assert.False(CoreActionProof.ContainerEmptied(true,true,0,0,0.5));Assert.False(CoreActionProof.ContainerEmptied(true,true,3,1,0.5));Assert.False(CoreActionProof.ContainerEmptied(true,true,3,0,10.1));Assert.False(CoreActionProof.ContainerEmptied(false,true,3,0,0.5));Assert.True(CoreActionProof.ItemUnequipped(true,true,false));Assert.False(CoreActionProof.ItemUnequipped(true,false,false));Assert.False(CoreActionProof.ItemUnequipped(true,true,true));Assert.False(CoreActionProof.PieceDestroyed(false));Assert.False(CoreActionProof.PieceRemoved(true,false));Assert.False(CoreActionProof.PieceRepaired(true,false));Assert.False(CoreActionProof.PlayerTeleported(true,false));Assert.True(CoreActionProof.PieceDestroyed(true));Assert.True(CoreActionProof.PieceRemoved(true,true));Assert.True(CoreActionProof.PieceRepaired(true,true));Assert.True(CoreActionProof.PlayerTeleported(true,true));}
  [Fact] public void CombatHarvestEventsNormalizeOnlyApprovedTargetsAndFields(){var at=DateTimeOffset.UnixEpoch;var damage=CombatHarvestEventContract.DamageDealt("$enemy_greyling(Clone)","Axes",true,at);Assert.Equal("damage_dealt",damage.Name);Assert.Equal("$enemy_greyling",damage.Target);Assert.Equal("Axes",damage.Fields["weapon_skill"]);Assert.Equal("true",damage.Fields["projectile"]);var resource=CombatHarvestEventContract.ResourceDamaged("Beech1(Clone)","Axes",false,at);Assert.Equal("Beech1",resource.Target);Assert.Equal("false",resource.Fields["projectile"]);Assert.Equal("resource_picked",CombatHarvestEventContract.ResourcePicked("RaspberryBush(Clone)",at).Name);Assert.Null(CombatHarvestEventContract.AttackBlocked(" ","Axes",false,at));Assert.Null(CombatHarvestEventContract.CharacterStaggered("Greydwarf"," ",false,at));Assert.DoesNotContain("player",JsonConvert.SerializeObject(damage),StringComparison.OrdinalIgnoreCase);}
  [Fact] public void CombatHarvestProofRejectsNoOpRemoteRepeatedAndRefusedPaths(){Assert.True(CombatHarvestProof.DamageDealt(true,true,20,15));Assert.False(CombatHarvestProof.DamageDealt(false,true,20,15));Assert.False(CombatHarvestProof.DamageDealt(true,false,20,15));Assert.False(CombatHarvestProof.DamageDealt(true,true,20,20));Assert.False(CombatHarvestProof.DamageDealt(true,true,double.NaN,15));Assert.True(CombatHarvestProof.CharacterStaggered(true,false,true));Assert.False(CombatHarvestProof.CharacterStaggered(true,true,true));Assert.False(CombatHarvestProof.CharacterStaggered(false,false,true));Assert.True(CombatHarvestProof.AttackBlocked(true,true));Assert.False(CombatHarvestProof.AttackBlocked(true,false));Assert.True(CombatHarvestProof.ResourceDamaged(true,true,true));Assert.False(CombatHarvestProof.ResourceDamaged(true,false,true));Assert.False(CombatHarvestProof.ResourceDamaged(true,true,false));Assert.True(CombatHarvestProof.ResourcePicked(true,true,false,true));Assert.False(CombatHarvestProof.ResourcePicked(false,true,false,true));Assert.False(CombatHarvestProof.ResourcePicked(true,true,true,true));Assert.False(CombatHarvestProof.ResourcePicked(true,true,false,false));}
  [Fact] public void CraftingEventsExposeOnlyNormalizedStationItemAndQuantity(){var at=DateTimeOffset.UnixEpoch;Assert.Equal("piece_workbench",CraftingEventContract.ItemCrafted("piece_workbench(Clone)",at).Target);Assert.Equal("handcrafting",CraftingEventContract.ItemCrafted(null,at).Target);var input=CraftingEventContract.StationInputAdded("smelter(Clone)","CopperOre(Clone)",at);Assert.Equal("CopperOre",input.Target);Assert.Equal("smelter",input.Fields["station"]);Assert.Equal("1",input.Fields["quantity"]);var output=CraftingEventContract.StationOutputProduced("smelter","Copper",3,at);Assert.Equal("3",output.Fields["quantity"]);Assert.Null(CraftingEventContract.StationOutputProduced("smelter","Copper",0,at));Assert.DoesNotContain("sender",JsonConvert.SerializeObject(input),StringComparison.OrdinalIgnoreCase);}
  [Fact] public void CraftingProofRejectsFailedRemoteFullAndZeroQuantityPaths(){Assert.True(CraftingProof.ItemCrafted(true,true,1,2));Assert.False(CraftingProof.ItemCrafted(true,false,1,2));Assert.False(CraftingProof.ItemCrafted(true,true,2,2));Assert.True(CraftingProof.StationValueIncreased(true,true,1,2));Assert.False(CraftingProof.StationValueIncreased(true,true,2,2));Assert.False(CraftingProof.StationValueIncreased(false,true,1,2));Assert.True(CraftingProof.StationSlotAdded(true,true,0,1));Assert.False(CraftingProof.StationSlotAdded(true,false,0,1));Assert.True(CraftingProof.StationOutputCollected(true,true,1,0,1));Assert.False(CraftingProof.StationOutputCollected(true,true,1,1,1));Assert.False(CraftingProof.StationOutputCollected(true,true,1,0,0));Assert.True(CraftingProof.StationOutputProduced(true,true,2));Assert.False(CraftingProof.StationOutputProduced(false,true,2));Assert.False(CraftingProof.StationOutputProduced(true,false,2));}
  const string Valid = """{"schema":"comfy-quest-experience/v1","id":"hello","entry_stage":"start","stages":[{"id":"start","transitions":[{"id":"done","priority":1,"when":{"op":"EVENT","event":"kill","target":"Troll"},"actions":[{"id":"say","type":"message","text":"Skal!"}],"outcome":"complete"}]}],"bindings":[{"id":"sign","experience_id":"hello"}]}""";
  [Fact] public void CompilesMinimalExperience(){var c=ExperienceCompiler.CompileJson(Valid,new HashSet<string>{"kill"});Assert.True(c.IsValid,string.Join(";",c.Diagnostics));}
  [Fact] public void RejectsCycles(){var json=Valid.Replace("\"outcome\":\"complete\"","\"next_stage\":\"start\"");Assert.Contains(ExperienceCompiler.CompileJson(json,new HashSet<string>{"kill"}).Diagnostics,x=>x.Code=="graph.cycle");}
  [Fact] public void EvaluatesSequenceDeterministically(){var x=new TriggerExpression{Op="SEQUENCE",Children=new(){new(){Op="EVENT",Event="hit"},new(){Op="EVENT",Event="kill"}}};var h=new[]{new RuntimeEvent{Name="hit",At=DateTimeOffset.UnixEpoch},new RuntimeEvent{Name="kill",At=DateTimeOffset.UnixEpoch.AddSeconds(1)}};Assert.True(TriggerEvaluator.Matches(x,h));Assert.False(TriggerEvaluator.Matches(x,new[]{h[1],h[0]}));}
  [Fact] public void RejectsUnknownActions(){Assert.Contains(ExperienceCompiler.CompileJson(Valid.Replace("message","shell"),new HashSet<string>{"kill"}).Diagnostics,x=>x.Code=="action.unsupported");}
  [Fact] public void RejectsUnboundedOrUnknownActionParameters(){var excessive=Valid.Replace("\"text\":\"Skal!\"","\"text\":\"Skal!\",\"command\":\"nocost\"");Assert.Contains(ExperienceCompiler.CompileJson(excessive,new HashSet<string>{"kill"}).Diagnostics,x=>x.Code=="action.parameter_unknown");var spawn=Valid.Replace("{\"id\":\"say\",\"type\":\"message\",\"text\":\"Skal!\"}","{\"id\":\"say\",\"type\":\"spawn\",\"kind\":\"creature\",\"prefab\":\"Greydwarf\",\"count\":17,\"radius\":30}");Assert.Contains(ExperienceCompiler.CompileJson(spawn,new HashSet<string>{"kill"}).Diagnostics,x=>x.Code=="action.parameter");}
  [Fact] public void ExperienceAndLegacyCatalogsStayIdentical(){Assert.Equal(new HashSet<string>(QuestEventCatalog.AllEventNames,StringComparer.OrdinalIgnoreCase),new HashSet<string>(CanonicalEventCatalog.All,StringComparer.OrdinalIgnoreCase));}
  [Fact] public void GeneratedCreatorAndRuntimeBoundariesHaveExactCounts(){Assert.Equal(34,CreatorEventCatalog.Count);Assert.Equal(34,RuntimeProductionEventCatalog.Count);Assert.Equal(2,RuntimeProductionEventCatalog.EngineEvents.Count);Assert.Equal(57,RuntimeWitnessCatalog.Count);foreach(var name in new[]{"kill","container_emptied","item_unequipped","piece_destroyed","piece_removed","piece_repaired","player_teleported","attack_blocked","character_staggered","damage_dealt","resource_damaged","resource_picked","item_crafted","station_fuel_added","station_input_added","station_output_collected","station_output_produced","global_key_removed","global_key_set","max_health_changed","player_died","skill_raised","skills_lowered","stamina_gained","stamina_spent"})Assert.True(RuntimeProductionEventCatalog.Contains(name),name);foreach(var creator in CreatorEventCatalog.All)Assert.True(creator.ProductionAvailable,creator.Name);}
  [Theory][InlineData("container_emptied","piece_chest_wood")][InlineData("item_unequipped","AxeBronze")][InlineData("piece_destroyed","wood_wall")][InlineData("piece_removed","piece")][InlineData("piece_repaired","wood_wall")] public void CoreLocalActionsCompileWithExactOrWildcardTargets(string eventName,string target){var exact=Valid.Replace("\"event\":\"kill\",\"target\":\"Troll\"",$"\"event\":\"{eventName}\",\"target\":\"{target}\"");Assert.True(ExperienceCompiler.CompileProductionJson(exact).IsValid);var wildcard=Valid.Replace("\"event\":\"kill\",\"target\":\"Troll\"",$"\"event\":\"{eventName}\"");Assert.True(ExperienceCompiler.CompileProductionJson(wildcard).IsValid);}
  [Fact] public void SuccessfulTeleportIsTargetless(){var valid=Valid.Replace("\"event\":\"kill\",\"target\":\"Troll\"","\"event\":\"player_teleported\"");Assert.True(ExperienceCompiler.CompileProductionJson(valid).IsValid);Assert.Contains(ExperienceCompiler.CompileProductionJson(valid.Replace("\"event\":\"player_teleported\"","\"event\":\"player_teleported\",\"target\":\"portal\"")).Diagnostics,x=>x.Code=="trigger.target_unsupported");}
  [Theory][InlineData("attack_blocked","$enemy_greyling")][InlineData("character_staggered","$enemy_greyling")][InlineData("damage_dealt","$enemy_greyling")][InlineData("resource_damaged","Beech1")][InlineData("resource_picked","RaspberryBush")] public void CombatHarvestEventsCompileWithExactOrWildcardTargets(string eventName,string target){var exact=Valid.Replace("\"event\":\"kill\",\"target\":\"Troll\"",$"\"event\":\"{eventName}\",\"target\":\"{target}\"");Assert.True(ExperienceCompiler.CompileProductionJson(exact).IsValid);var wildcard=Valid.Replace("\"event\":\"kill\",\"target\":\"Troll\"",$"\"event\":\"{eventName}\"");Assert.True(ExperienceCompiler.CompileProductionJson(wildcard).IsValid);}
  [Fact] public void ProductionCompilerRejectsNonCreatorEventsAndDeadConstraints(){Assert.True(ExperienceCompiler.CompileProductionJson(Valid).IsValid);var unsupported=Valid.Replace("\"event\":\"kill\"","\"event\":\"inventory_item_added\"");Assert.Contains(ExperienceCompiler.CompileProductionJson(unsupported).Diagnostics,x=>x.Code=="event.not_production");var dead=Valid.Replace("\"target\":\"Troll\"","\"target\":\"Troll\",\"where\":{\"amount\":\"1\"}");Assert.Contains(ExperienceCompiler.CompileProductionJson(dead).Diagnostics,x=>x.Code=="trigger.where_unsupported");}
  [Theory][InlineData("projectile","any")][InlineData("projectile","false")][InlineData("weapon_skill","")][InlineData("weapon_skill","                                                                                                                                x")] public void ProductionCompilerRejectsInvalidWhereValues(string field,string value){var json=Valid.Replace("\"target\":\"Troll\"",$"\"target\":\"Troll\",\"where\":{{\"{field}\":\"{value}\"}}");Assert.Contains(ExperienceCompiler.CompileProductionJson(json).Diagnostics,x=>x.Code=="trigger.where_value");}
  [Theory][InlineData("NaN")][InlineData("Infinity")][InlineData("-1")][InlineData("0")] public void ProductionCompilerRequiresPositiveFiniteAmounts(string value){var json=Valid.Replace("\"event\":\"kill\",\"target\":\"Troll\"",$"\"event\":\"character_healed\",\"target\":\"you\",\"where\":{{\"amount\":\"{value}\"}}");Assert.Contains(ExperienceCompiler.CompileProductionJson(json).Diagnostics,x=>x.Code=="trigger.where_value");}
  [Fact] public void ProductionCompilerEnforcesAdapterFixedFields(){var placed=Valid.Replace("\"event\":\"kill\",\"target\":\"Troll\"","\"event\":\"piece_placed\",\"target\":\"wood_wall\",\"where\":{\"actor_role\":\"peer\"}");Assert.Contains(ExperienceCompiler.CompileProductionJson(placed).Diagnostics,x=>x.Code=="trigger.where_fixed");Assert.True(ExperienceCompiler.CompileProductionJson(placed.Replace("\"peer\"","\"listen_host\"")).IsValid);}
  [Fact] public void ProductionCompilerRejectsTargetsAdaptersCannotEmit(){var heal=Valid.Replace("\"event\":\"kill\",\"target\":\"Troll\"","\"event\":\"character_healed\",\"target\":\"someone_else\"");Assert.Contains(ExperienceCompiler.CompileProductionJson(heal).Diagnostics,x=>x.Code=="trigger.target_fixed");var chat=Valid.Replace("\"event\":\"kill\",\"target\":\"Troll\"","\"event\":\"chat_sent\",\"target\":\"whisper\"");Assert.Contains(ExperienceCompiler.CompileProductionJson(chat).Diagnostics,x=>x.Code=="trigger.target_value");Assert.True(ExperienceCompiler.CompileProductionJson(chat.Replace("\"whisper\"","\"normal\"")).IsValid);var timer=Valid.Replace("\"event\":\"kill\",\"target\":\"Troll\"","\"event\":\"timer_elapsed\",\"target\":\"bell\",\"where\":{\"timer_id\":\"bell\"}");Assert.Contains(ExperienceCompiler.CompileProductionJson(timer).Diagnostics,x=>x.Code=="trigger.target_unsupported");}
  [Fact] public void RuntimeNormalizationDropsUnknownPayloadAndRejectsNonCreatorEvents(){var normalized=RuntimeEventPolicy.Normalize(new RuntimeEvent{Name="character_healed",Target="you(Clone)",At=DateTimeOffset.UnixEpoch,Fields=new Dictionary<string,string>{{"amount","2.5"},{"player_name","secret"}}});Assert.Equal("you",normalized.Target);Assert.Equal("2.5",normalized.Fields["amount"]);Assert.False(normalized.Fields.ContainsKey("player_name"));var combat=RuntimeEventPolicy.Normalize(new RuntimeEvent{Name="attack_blocked",Target="Greydwarf(Clone)",Fields=new Dictionary<string,string>{{"weapon_skill","Blocking"},{"projectile","false"},{"player_name","secret"}}});Assert.Equal("Greydwarf",combat.Target);Assert.Equal(2,combat.Fields.Count);var progression=RuntimeEventPolicy.Normalize(new RuntimeEvent{Name="max_health_changed",Target="health",Fields=new Dictionary<string,string>{{"subject","health"},{"amount","125"},{"player_name","secret"}}});Assert.Equal("health",progression.Target);Assert.Equal(2,progression.Fields.Count);Assert.Null(RuntimeEventPolicy.Normalize(new RuntimeEvent{Name="inventory_item_added",Target="Wood"}));}
  [Fact] public void RuntimeNormalizationEnforcesClosedAndFixedTargets(){Assert.Null(RuntimeEventPolicy.Normalize(new RuntimeEvent{Name="character_healed",Target="someone_else"}));Assert.Null(RuntimeEventPolicy.Normalize(new RuntimeEvent{Name="chat_sent",Target="whisper"}));Assert.Equal("normal",RuntimeEventPolicy.Normalize(new RuntimeEvent{Name="chat_sent",Target="normal"}).Target);Assert.Null(RuntimeEventPolicy.Normalize(new RuntimeEvent{Name="timer_elapsed",Target="bell",Fields=new Dictionary<string,string>{{"timer_id","bell"}}}));}
  [Fact] public void RuntimeActionCorrelationJoinsAlternateWitnessButNotRepeat(){var dedupe=new RuntimeActionDedupe();var first=dedupe.Key("heal","player","2.5","Character.Heal",10);var alternate=dedupe.Key("heal","player","2.5","Character.RPC_Heal",10.1);var repeat=dedupe.Key("heal","player","2.5","Character.Heal",10.2);Assert.Equal(first,alternate);Assert.NotEqual(first,repeat);}
  [Fact] public void DefaultPackInspectionUsesProductionBoundary(){var root=Path.Combine(Path.GetTempPath(),"comfy-pack-"+Guid.NewGuid().ToString("N"));try{var inbox=Directory.CreateDirectory(Path.Combine(root,"inbox")).FullName;var path=Path.Combine(inbox,"unsupported.questpack");WritePack(path,"1.0.0",Valid.Replace("\"event\":\"kill\"","\"event\":\"inventory_item_added\""));Assert.Contains(new QuestPackStore(root).Inspect(path).Diagnostics,x=>x.Code=="event.not_production");}finally{Directory.Delete(root,true);}}
  [Fact] public void ProgressionAndWorldContractsRequireActualBoundedChanges(){var health=ProgressionEventContract.MaxHealthChanged(125f,DateTimeOffset.UnixEpoch);Assert.Equal("health",health.Target);Assert.Equal("health",health.Fields["subject"]);Assert.Equal("125",health.Fields["amount"]);var skill=ProgressionEventContract.SkillRaised("Axes",1.5f,DateTimeOffset.UnixEpoch);Assert.Equal("Axes",skill.Target);Assert.Equal("Axes",skill.Fields["subject"]);Assert.Null(ProgressionEventContract.StaminaSpent(0f,DateTimeOffset.UnixEpoch));Assert.True(ProgressionProof.ValueChanged(true,100,125));Assert.False(ProgressionProof.ValueChanged(true,100,100));Assert.True(ProgressionProof.ValueIncreased(true,10,15));Assert.False(ProgressionProof.ValueIncreased(false,10,15));Assert.True(ProgressionProof.ValueDecreased(true,15,10));Assert.True(ProgressionProof.SkillRaised(true,7,0.2,7,0.3));Assert.True(ProgressionProof.SkillRaised(true,7,0.9,8,0));Assert.False(ProgressionProof.SkillRaised(true,7,0.2,7,0.2));Assert.True(ProgressionProof.SkillsLowered(true,0.05,100,1,95,0));Assert.False(ProgressionProof.SkillsLowered(true,0,100,1,100,0));Assert.True(ProgressionProof.PlayerDied(true,true,false,true));Assert.False(ProgressionProof.PlayerDied(true,false,false,true));var set=WorldStateEventContract.GlobalKeySet("defeated_eikthyr",DateTimeOffset.UnixEpoch);Assert.Equal("defeated_eikthyr",set.Target);Assert.True(WorldStateProof.GlobalKeySet(true,false,true));Assert.False(WorldStateProof.GlobalKeySet(true,true,true));Assert.True(WorldStateProof.GlobalKeyRemoved(true,true,false));Assert.False(WorldStateProof.GlobalKeyRemoved(false,true,false));}
  [Fact] public void ActivatesOnlyOnExplicitLoad(){var root=Path.Combine(Path.GetTempPath(),"comfy-pack-"+Guid.NewGuid().ToString("N"));try{var inbox=Directory.CreateDirectory(Path.Combine(root,"inbox")).FullName;WritePack(Path.Combine(inbox,"hello.questpack"),"1.0.0",Valid);var store=new QuestPackStore(root);Assert.False(File.Exists(Path.Combine(root,"active","active-set.json")));Assert.Single(store.CheckInbox(new HashSet<string>{"kill"}));var loaded=store.LoadLatest(new HashSet<string>{"kill"});Assert.Equal("1.0.0",loaded.Manifest.Version);Assert.True(File.Exists(Path.Combine(root,"active","active-set.json")));}finally{Directory.Delete(root,true);}}
  [Fact] public void SameVersionDifferentContentFailsClosed(){var root=Path.Combine(Path.GetTempPath(),"comfy-pack-"+Guid.NewGuid().ToString("N"));try{var inbox=Directory.CreateDirectory(Path.Combine(root,"inbox")).FullName;WritePack(Path.Combine(inbox,"a.questpack"),"1.0.0",Valid);WritePack(Path.Combine(inbox,"b.questpack"),"1.0.0",Valid.Replace("Skal!","Hail!"));var store=new QuestPackStore(root);Assert.Throws<InvalidOperationException>(()=>store.LoadLatest(new HashSet<string>{"kill"}));}finally{Directory.Delete(root,true);}}
  [Fact] public void RejectsUnsupportedArchiveEntries(){var root=Path.Combine(Path.GetTempPath(),"comfy-pack-"+Guid.NewGuid().ToString("N"));try{var inbox=Directory.CreateDirectory(Path.Combine(root,"inbox")).FullName;var path=Path.Combine(inbox,"unsafe.questpack");WritePack(path,"1.0.0",Valid);using(var zip=ZipFile.Open(path,ZipArchiveMode.Update))using(var writer=new StreamWriter(zip.CreateEntry("scripts/run.txt").Open()))writer.Write("no");Assert.Contains(new QuestPackStore(root).Inspect(path,new HashSet<string>{"kill"}).Diagnostics,x=>x.Code=="pack.path");}finally{Directory.Delete(root,true);}}
  [Fact] public void SelectsVersionAndRollsBackWithFreshActivationEpochs(){var root=Path.Combine(Path.GetTempPath(),"comfy-pack-"+Guid.NewGuid().ToString("N"));try{var inbox=Directory.CreateDirectory(Path.Combine(root,"inbox")).FullName;WritePack(Path.Combine(inbox,"one.questpack"),"1.0.0",Valid);WritePack(Path.Combine(inbox,"two.questpack"),"2.0.0",Valid.Replace("Skal!","Hail!"));var store=new QuestPackStore(root);Assert.Equal("2.0.0",store.LoadLatest(new HashSet<string>{"kill"}).Manifest.Version);var first=ReadActive(root);Assert.Matches("^act-[0-9]{8}T[0-9]{9}Z-[0-9a-f]{8}$",first.ActivationId);Assert.Equal("comfy-quest-active-set/v1",first.Schema);Assert.Equal("1.0.0",store.LoadVersion("demo","1.0.0",new HashSet<string>{"kill"}).Manifest.Version);var second=ReadActive(root);Assert.NotEqual(first.ActivationId,second.ActivationId);Assert.Equal("2.0.0",store.Rollback(new HashSet<string>{"kill"}).Manifest.Version);var rollback=ReadActive(root);Assert.Equal("2.0.0",rollback.Version);Assert.NotEqual(first.ActivationId,rollback.ActivationId);Assert.NotEqual(second.ActivationId,rollback.ActivationId);Assert.False(File.Exists(Path.Combine(root,"active","active-set.json.tmp")));}finally{Directory.Delete(root,true);}}
  [Fact] public void DevLaneActivatesExactRevisionWithoutPollutingProduction(){var root=Path.Combine(Path.GetTempPath(),"comfy-pack-"+Guid.NewGuid().ToString("N"));try{var inbox=Directory.CreateDirectory(Path.Combine(root,"inbox")).FullName;var dev=Directory.CreateDirectory(Path.Combine(root,"inbox-dev")).FullName;WritePack(Path.Combine(inbox,"public.questpack"),"1.0.0",Valid);WritePack(Path.Combine(dev,"r1.questpack"),"1.0.0",Valid.Replace("Skal!","First"));WritePack(Path.Combine(dev,"r2.questpack"),"1.0.0",Valid.Replace("Skal!","Second"));var store=new QuestPackStore(root);Assert.Single(store.CheckInbox(new HashSet<string>{"kill"}));Assert.Equal(2,store.CheckDevInbox(new HashSet<string>{"kill"}).Count);Assert.Contains(store.Inspect(Path.Combine(dev,"r1.questpack"),new HashSet<string>{"kill"}).Diagnostics,x=>x.Code=="pack.path");var chosen=store.LoadDevRevision("r2.questpack",new HashSet<string>{"kill"});Assert.Equal(QuestPackLane.Dev,chosen.Lane);var active=ReadActive(root);Assert.Equal("dev",active.SourceChannel);Assert.Equal("r2.questpack",active.Source);Assert.Null(active.PreviousActivationId);}finally{Directory.Delete(root,true);}}
  [Fact] public void RollbackWalksActivationLineageAndSupportsAddressedHistory(){var root=Path.Combine(Path.GetTempPath(),"comfy-pack-"+Guid.NewGuid().ToString("N"));try{var inbox=Directory.CreateDirectory(Path.Combine(root,"inbox")).FullName;WritePack(Path.Combine(inbox,"one.questpack"),"1.0.0",Valid);WritePack(Path.Combine(inbox,"two.questpack"),"2.0.0",Valid.Replace("Skal!","Two"));WritePack(Path.Combine(inbox,"three.questpack"),"3.0.0",Valid.Replace("Skal!","Three"));var store=new QuestPackStore(root);store.LoadVersion("demo","1.0.0",new HashSet<string>{"kill"});var first=ReadActive(root);store.LoadVersion("demo","2.0.0",new HashSet<string>{"kill"});var second=ReadActive(root);store.LoadVersion("demo","3.0.0",new HashSet<string>{"kill"});Assert.Equal("2.0.0",store.Rollback(new HashSet<string>{"kill"}).Manifest.Version);var rollbackTwo=ReadActive(root);Assert.Equal(first.ActivationId,rollbackTwo.PreviousActivationId);Assert.Equal("1.0.0",store.Rollback(new HashSet<string>{"kill"}).Manifest.Version);var rollbackOne=ReadActive(root);Assert.Null(rollbackOne.PreviousActivationId);Assert.Null(store.Rollback(new HashSet<string>{"kill"}));Assert.Equal("2.0.0",store.Rollback(second.ActivationId,new HashSet<string>{"kill"}).Manifest.Version);Assert.NotEqual(second.ActivationId,ReadActive(root).ActivationId);}finally{Directory.Delete(root,true);}}
