  [Fact] public void OldRuntimeReceiptRoundTripsWithAdditiveFieldsOmitted(){var json=File.ReadAllText(Fixture("runtime-receipt-v1.json"));var receipt=JsonConvert.DeserializeObject<RuntimeReceipt>(json);Assert.Equal("comfy-quest-runtime-receipt/v1",receipt.Schema);Assert.Null(receipt.ActivationId);Assert.Null(receipt.CorrelationId);Assert.Null(receipt.StageEnteredUtc);Assert.Null(receipt.Evidence);Assert.Null(receipt.RejectedEvidence);var oldRoundTrip=JsonConvert.SerializeObject(receipt);foreach(var field in new[]{"activation_id","correlation_id","stage_entered_utc","evidence","rejected_evidence"})Assert.DoesNotContain("\""+field+"\"",oldRoundTrip);receipt.ActivationId="act-19700101T000000000Z-deadbeef";receipt.CorrelationId="evt-0123456789ab";receipt.StageEnteredUtc=DateTimeOffset.UnixEpoch;receipt.Evidence=new TriggerClauseTrace{Op="EVENT",Event="kill",Satisfied=true,Current=1,Required=1};receipt.RejectedEvidence=new[]{new RejectedTransitionEvidence{TransitionId="other",Evidence=new TriggerClauseTrace{Op="EVENT",Event="hit",Satisfied=false,Current=0,Required=1}}};var populated=JsonConvert.DeserializeObject<RuntimeReceipt>(JsonConvert.SerializeObject(receipt));Assert.Equal(receipt.ActivationId,populated.ActivationId);Assert.Equal(receipt.CorrelationId,populated.CorrelationId);Assert.Equal(receipt.StageEnteredUtc,populated.StageEnteredUtc);Assert.True(populated.Evidence.Satisfied);Assert.Equal("other",Assert.Single(populated.RejectedEvidence).TransitionId);}
  [Fact] public void ExplainIsDeterministicAndAgreesWithMatchesForEveryOperator(){var at=DateTimeOffset.UnixEpoch;var history=new[]{new RuntimeEvent{Name="hit",Target="Troll",At=at,Fields=new Dictionary<string,string>{{"actor_role","peer"}}},new RuntimeEvent{Name="hit",Target="Troll",At=at.AddSeconds(2),Fields=new Dictionary<string,string>{{"actor_role","peer"}}},new RuntimeEvent{Name="kill",Target="Troll",At=at.AddSeconds(3)}};var hit=new TriggerExpression{Op="EVENT",Event="hit",Target="Troll",Where=new(){{"actor_role","peer"}}};var kill=new TriggerExpression{Op="EVENT",Event="kill",Target="Troll"};var miss=new TriggerExpression{Op="EVENT",Event="hit",Target="Greydwarf"};var cases=new[]{hit,miss,new TriggerExpression{Op="ANY",Children=new(){miss,kill}},new TriggerExpression{Op="ANY",Children=new(){miss,new(){Op="EVENT",Event="missing"}}},new TriggerExpression{Op="ALL",Children=new(){hit,kill}},new TriggerExpression{Op="ALL",Children=new(){hit,miss}},new TriggerExpression{Op="COUNT",Count=2,Children=new(){hit}},new TriggerExpression{Op="COUNT",Count=3,Children=new(){hit}},new TriggerExpression{Op="SEQUENCE",Children=new(){hit,kill}},new TriggerExpression{Op="SEQUENCE",Children=new(){kill,hit}},new TriggerExpression{Op="COUNT",Count=1,WithinSeconds=1,Children=new(){hit}}};foreach(var expression in cases){var expected=TriggerEvaluator.Matches(expression,history);var first=TriggerEvaluator.Explain(expression,history);var second=TriggerEvaluator.Explain(expression,history);Assert.Equal(expected,first.Satisfied);Assert.Equal(JsonConvert.SerializeObject(first),JsonConvert.SerializeObject(second));}var count=TriggerEvaluator.Explain(cases[6],history);Assert.Equal(2,count.Current);Assert.Equal(2,count.Required);var sequence=TriggerEvaluator.Explain(cases[8],history);Assert.Equal(2,sequence.SequenceIndex);Assert.Equal(1,TriggerEvaluator.Explain(cases[10],history).WithinSeconds);var nestedWindow=new TriggerExpression{Op="ALL",Children=new(){new(){Op="EVENT",Event="hit",WithinSeconds=1}}};var nestedTrace=TriggerEvaluator.Explain(nestedWindow,history);Assert.Equal(TriggerEvaluator.Matches(nestedWindow,history),nestedTrace.Satisfied);Assert.Null(Assert.Single(nestedTrace.Children).WithinSeconds);var overshoot=new TriggerExpression{Op="COUNT",Count=1,Children=new(){hit}};var measured=TriggerEvaluator.Measure(overshoot,history);var explained=TriggerEvaluator.Explain(overshoot,history);Assert.Equal(measured.Current,explained.Current);Assert.Equal(measured.Required,explained.Required);Assert.Equal(1,explained.Current);}
  [Fact] public void ExplainKeepsRelevantWhereActualsAndEnforcesEvidenceBounds(){var where=Enumerable.Range(0,12).ToDictionary(x=>$"field-{x:00}",x=>$"value-{x:00}",StringComparer.Ordinal);var expression=new TriggerExpression{Op="EVENT",Event="signal",Where=where};var history=new[]{new RuntimeEvent{Name="signal",At=DateTimeOffset.UnixEpoch,Fields=where}};var bounded=TriggerEvaluator.Explain(expression,history);Assert.True(bounded.Satisfied);Assert.Equal(TriggerEvaluator.MaxTraceWhereEntries,bounded.Where.Count);Assert.True(bounded.Truncated);var mismatchedFields=new Dictionary<string,string>(where,StringComparer.Ordinal);mismatchedFields["field-11"]="wrong";var cappedMismatch=TriggerEvaluator.Explain(expression,new[]{new RuntimeEvent{Name="signal",At=DateTimeOffset.UnixEpoch,Fields=mismatchedFields}});var failed=Assert.Single(cappedMismatch.Where,item=>!item.Satisfied);Assert.Equal("field-11",failed.Field);Assert.Equal("value-11",failed.Expected);Assert.Equal("wrong",failed.Actual);Assert.True(cappedMismatch.Truncated);var latest=TriggerEvaluator.Explain(new TriggerExpression{Op="EVENT",Event="signal",Where=new(){{"state","expected"}}},new[]{new RuntimeEvent{Name="signal",At=DateTimeOffset.UnixEpoch,Fields=new Dictionary<string,string>{{"state","old"}}},new RuntimeEvent{Name="signal",At=DateTimeOffset.UnixEpoch.AddSeconds(1),Fields=new Dictionary<string,string>{{"state","latest"}}}});Assert.Equal("latest",Assert.Single(latest.Where).Actual);var large=new TriggerExpression{Op="ALL",Children=Enumerable.Range(0,128).Select(x=>new TriggerExpression{Op="EVENT",Event=$"event-{x:000}",Target=new string('x',128),Where=Enumerable.Range(0,12).ToDictionary(y=>$"field-{y:00}",y=>new string('v',128),StringComparer.Ordinal)}).ToList()};var trace=TriggerEvaluator.Explain(large,Array.Empty<RuntimeEvent>());Assert.Equal(TriggerEvaluator.Matches(large,Array.Empty<RuntimeEvent>()),trace.Satisfied);Assert.True(trace.Truncated==true);Assert.All(TraceNodes(trace),node=>Assert.InRange(node.Where.Count,0,TriggerEvaluator.MaxTraceWhereEntries));Assert.True(Encoding.UTF8.GetByteCount(JsonConvert.SerializeObject(trace,Formatting.Indented))<=TriggerEvaluator.MaxTraceSerializedBytes);}
  [Fact]
  public void AdaptiveThresholdSchemaMovesAsOneClosedGate() {
    Assert.Equal(new[]{"time_since_progress","time_since_stage_entered"},AdaptiveMeasureCatalog.All.Select(x=>x.Name).OrderBy(x=>x,StringComparer.Ordinal));
    Assert.All(AdaptiveMeasureCatalog.All,x=>Assert.Equal("extended",x.Palette));
    var adaptive=Valid.Replace("\"when\":{\"op\":\"EVENT\",\"event\":\"kill\",\"target\":\"Troll\"}","\"when\":{\"op\":\"ALL\",\"children\":[{\"op\":\"EVENT\",\"event\":\"kill\",\"target\":\"Troll\"},{\"op\":\"THRESHOLD\",\"measure\":\"time_since_stage_entered\",\"comparison\":\"gte\",\"value\":30}]}");
    Assert.True(ExperienceCompiler.CompileJson(adaptive,new HashSet<string>{"kill"}).IsValid);
    Assert.Contains(ExperienceCompiler.CompileJson(adaptive.Replace("time_since_stage_entered","invented_measure"),new HashSet<string>{"kill"}).Diagnostics,x=>x.Code=="threshold.measure");
    Assert.Contains(ExperienceCompiler.CompileJson(adaptive.Replace("\"gte\"","\"lte\""),new HashSet<string>{"kill"}).Diagnostics,x=>x.Code=="threshold.comparison");
    Assert.Contains(ExperienceCompiler.CompileJson(adaptive.Replace("\"value\":30","\"value\":0"),new HashSet<string>{"kill"}).Diagnostics,x=>x.Code=="threshold.value");
    var undriven=Valid.Replace("{\"op\":\"EVENT\",\"event\":\"kill\",\"target\":\"Troll\"}","{\"op\":\"THRESHOLD\",\"measure\":\"time_since_stage_entered\",\"comparison\":\"gte\",\"value\":30}");
    Assert.Contains(ExperienceCompiler.CompileJson(undriven,new HashSet<string>{"kill"}).Diagnostics,x=>x.Code=="trigger.event_driver");
    var child=adaptive.Replace("\"value\":30}","\"value\":30,\"children\":[{\"op\":\"EVENT\",\"event\":\"kill\"}]}");
    Assert.Contains(ExperienceCompiler.CompileJson(child,new HashSet<string>{"kill"}).Diagnostics,x=>x.Code=="threshold.children");
  }
  [Fact]
  public void AdaptiveThresholdUsesEventTimeAndExplainsActualVersusExpected() {
    var start=DateTimeOffset.Parse("2026-08-19T01:00:00Z");
    var history=new[]{new RuntimeEvent{Name="kill",Target="Troll",At=start.AddSeconds(45)}};
    var threshold=new TriggerExpression{Op="THRESHOLD",Measure="time_since_stage_entered",Comparison="gte",Value=30};
    var expression=new TriggerExpression{Op="ALL",Children=new(){new(){Op="EVENT",Event="kill",Target="Troll"},threshold}};
    var context=new TriggerEvaluationContext{At=history[0].At,StageEnteredUtc=start,LastProgressUtc=start.AddSeconds(20)};
    Assert.False(TriggerEvaluator.Matches(expression,history));
    Assert.True(TriggerEvaluator.Matches(expression,history,context));
    Assert.False(TriggerEvaluator.Matches(expression,history,new TriggerEvaluationContext{At=start.AddSeconds(29),StageEnteredUtc=start,LastProgressUtc=start}));
    var trace=TriggerEvaluator.Explain(expression,history,context);
    Assert.True(trace.Satisfied);
    Assert.Equal(2,trace.Current);
    Assert.Equal(2,trace.Required);
    var measured=Assert.Single(trace.Children,x=>x.Op=="THRESHOLD");
    Assert.Equal(30,measured.Current);
    Assert.Equal(30,measured.Required);
    var comparison=Assert.Single(measured.Where);
    Assert.Equal("time_since_stage_entered",comparison.Field);
    Assert.Equal(">= 30 seconds",comparison.Expected);
    Assert.Equal("45 seconds",comparison.Actual);
    Assert.True(comparison.Satisfied);
    Assert.Equal(JsonConvert.SerializeObject(trace),JsonConvert.SerializeObject(TriggerEvaluator.Explain(expression,history,context)));
    var quiet=new TriggerExpression{Op="THRESHOLD",Measure="time_since_progress",Comparison="gte",Value=30};
    Assert.False(TriggerEvaluator.Matches(quiet,history,context));
    context.At=start.AddSeconds(51);
    Assert.True(TriggerEvaluator.Matches(quiet,history,context));
  }
