  [Fact] public void WorkflowUsesEventTimeForCreationAdvanceAndReplay(){var root=Path.Combine(Path.GetTempPath(),"comfy-workflow-"+Guid.NewGuid().ToString("N"));try{var doc=TwoStage();var id=new WorkflowIdentity{WorldId="world",CharacterId="hero",BindingZdo="1:2",ContentHash=new string('a',64)};var created=DateTimeOffset.Parse("2026-08-18T01:00:00Z");var advanced=created.AddMinutes(2);var finished=advanced.AddMinutes(3);var store=new WorkflowStateStore(root);Assert.Null(store.Begin(id,doc,new RuntimeEvent{Name="ignored",At=created}));var initial=store.Get(id);Assert.Equal(created,initial.StageEnteredUtc);Assert.Equal(created,initial.LastEventUtc);var first=store.Begin(id,doc,new RuntimeEvent{Name="piece_damaged",At=advanced});Assert.Equal("first-hit",first.Transition.Id);Assert.Equal(advanced,first.EventAt);Assert.False(first.IsPendingReplay);Assert.DoesNotContain("EventAt",JsonConvert.SerializeObject(first));var replay=new WorkflowStateStore(root).Begin(id,doc,new RuntimeEvent{Name="piece_damaged",At=advanced.AddSeconds(30)});Assert.True(replay.IsPendingReplay);Assert.Equal(advanced,replay.EventAt);Assert.True(new WorkflowStateStore(root).Complete(replay));var second=new WorkflowStateStore(root).Get(id);Assert.Equal("second",second.StageId);Assert.Equal(advanced,second.StageEnteredUtc);Assert.Equal(advanced,second.LastEventUtc);var finish=new WorkflowStateStore(root).Begin(id,doc,new RuntimeEvent{Name="piece_damaged",At=finished});Assert.Equal("finish",finish.Transition.Id);Assert.True(new WorkflowStateStore(root).Complete(finish));var complete=new WorkflowStateStore(root).Get(id);Assert.Equal("complete",complete.Outcome);Assert.Equal(advanced,complete.StageEnteredUtc);Assert.Equal(finished,complete.LastEventUtc);Assert.Null(new WorkflowStateStore(root).Begin(id,doc,new RuntimeEvent{Name="piece_damaged",At=finished.AddSeconds(1)}));}finally{Directory.Delete(root,true);}}
