  [Fact] public void WorkflowFailsClosedWhenPendingEventTimeIsMissing(){var root=Path.Combine(Path.GetTempPath(),"comfy-workflow-"+Guid.NewGuid().ToString("N"));try{var doc=TwoStage();var id=new WorkflowIdentity{WorldId="world",CharacterId="hero",BindingZdo="1:2",ContentHash="hash"};var at=DateTimeOffset.Parse("2026-08-18T05:00:00Z");var decision=new WorkflowStateStore(root).Begin(id,doc,new RuntimeEvent{Name="piece_damaged",At=at});decision.EventAt=null;Assert.False(new WorkflowStateStore(root).Complete(decision));Assert.Equal("first",new WorkflowStateStore(root).Get(id).StageId);var replay=new WorkflowStateStore(root).Begin(id,doc,new RuntimeEvent{Name="piece_damaged",At=at.AddMinutes(1)});Assert.Equal(at,replay.EventAt);Assert.True(new WorkflowStateStore(root).Complete(replay));var legacyRoot=Path.Combine(root,"legacy");var state=Directory.CreateDirectory(Path.Combine(legacyRoot,"state")).FullName;File.Copy(Fixture("workflow-state-v1-pending-without-event-time.json"),Path.Combine(state,"workflow-states.json"));var legacyId=new WorkflowIdentity{WorldId="pending-world",CharacterId="pending-hero",BindingZdo="pending-zdo",ContentHash="pending-hash"};var legacyStore=new WorkflowStateStore(legacyRoot);Assert.Null(legacyStore.Begin(legacyId,doc,new RuntimeEvent{Name="piece_damaged",At=at}));var pending=legacyStore.Get(legacyId);Assert.NotNull(pending.History);Assert.Empty(pending.History);Assert.Equal("first-hit",pending.PendingTransitionId);Assert.Equal("first",pending.StageId);}finally{Directory.Delete(root,true);}}
