  [Fact] public void WorkflowAccumulatesBoundedCountAcrossEvents(){var root=Path.Combine(Path.GetTempPath(),"comfy-workflow-"+Guid.NewGuid().ToString("N"));try{var doc=TwoStage();doc.Stages[0].Transitions[0].When=new TriggerExpression{Op="COUNT",Count=2,Children=new(){new(){Op="EVENT",Event="piece_damaged"}}};var id=new WorkflowIdentity{WorldId="w",CharacterId="p",BindingZdo="z",ContentHash="h"};var store=new WorkflowStateStore(root);Assert.Null(store.Begin(id,doc,new RuntimeEvent{Name="piece_damaged",At=DateTimeOffset.UtcNow}));Assert.Equal("first-hit",store.Begin(id,doc,new RuntimeEvent{Name="piece_damaged",At=DateTimeOffset.UtcNow.AddSeconds(1)}).Transition.Id);}finally{Directory.Delete(root,true);}}
  [Fact] public void OldWorkflowStateLoadsWithNullTimestampsAndAdvances(){var root=Path.Combine(Path.GetTempPath(),"comfy-workflow-"+Guid.NewGuid().ToString("N"));try{var state=Directory.CreateDirectory(Path.Combine(root,"state")).FullName;File.Copy(Fixture("workflow-state-v1.json"),Path.Combine(state,"workflow-states.json"));var id=new WorkflowIdentity{WorldId="old-world",CharacterId="old-hero",BindingZdo="old-zdo",ContentHash="old-hash"};var store=new WorkflowStateStore(root);var old=store.Get(id);Assert.Equal("first",old.StageId);Assert.Null(old.StageEnteredUtc);Assert.Null(old.LastEventUtc);Assert.Null(old.LastProgressUtc);var at=DateTimeOffset.Parse("2026-08-18T02:00:00Z");var decision=store.Begin(id,TwoStage(),new RuntimeEvent{Name="piece_damaged",At=at});Assert.Equal(at,decision.EventAt);Assert.True(store.Complete(decision));var updated=store.Get(id);Assert.Equal("second",updated.StageId);Assert.Equal(at,updated.StageEnteredUtc);Assert.Equal(at,updated.LastEventUtc);Assert.Equal(at,updated.LastProgressUtc);}finally{Directory.Delete(root,true);}}
  [Fact]
  public void WorkflowPersistsTemporalProgressFromEventTimeOnly() {
    var root=Path.Combine(Path.GetTempPath(),"comfy-workflow-"+Guid.NewGuid().ToString("N"));
    try {
      var doc=TwoStage();
      doc.Stages[0].Transitions[0].When=new TriggerExpression{Op="ALL",Children=new(){new(){Op="EVENT",Event="piece_damaged"},new(){Op="THRESHOLD",Measure="time_since_stage_entered",Comparison="gte",Value=30},new(){Op="THRESHOLD",Measure="time_since_progress",Comparison="gte",Value=20}}};
      var id=new WorkflowIdentity{WorldId="w",CharacterId="p",BindingZdo="z",ContentHash="h"};
      var start=DateTimeOffset.Parse("2026-08-19T02:00:00Z");
      var store=new WorkflowStateStore(root);
      Assert.Null(store.Begin(id,doc,new RuntimeEvent{Name="ignored",At=start}));
      Assert.Equal(start,store.Get(id).LastProgressUtc);
      Assert.Null(store.Begin(id,doc,new RuntimeEvent{Name="ignored",At=start.AddSeconds(25)}));
      Assert.Equal(start,store.Get(id).LastProgressUtc);
      var decision=store.Begin(id,doc,new RuntimeEvent{Name="piece_damaged",At=start.AddSeconds(31)});
      Assert.NotNull(decision);
      Assert.Equal(start,decision.EvaluationContext.StageEnteredUtc);
      Assert.Equal(start,decision.EvaluationContext.LastProgressUtc);
      Assert.True(store.Complete(decision));
      var advanced=store.Get(id);
      Assert.Equal(start.AddSeconds(31),advanced.StageEnteredUtc);
      Assert.Equal(start.AddSeconds(31),advanced.LastEventUtc);
      Assert.Equal(start.AddSeconds(31),advanced.LastProgressUtc);
    } finally { Directory.Delete(root,true); }
  }
  [Fact]
  public void NoProgressThresholdResetsOnlyWhenStructuralEventProgressAdvances() {
    var root=Path.Combine(Path.GetTempPath(),"comfy-workflow-"+Guid.NewGuid().ToString("N"));
    try {
      var doc=TwoStage();
      doc.Stages[0].Transitions[0].When=new TriggerExpression{Op="ALL",Children=new(){new(){Op="COUNT",Count=2,Children=new(){new(){Op="EVENT",Event="piece_damaged"}}},new(){Op="THRESHOLD",Measure="time_since_progress",Comparison="gte",Value=20}}};
      var id=new WorkflowIdentity{WorldId="w",CharacterId="p",BindingZdo="z",ContentHash="quiet"};
      var start=DateTimeOffset.Parse("2026-08-19T03:00:00Z");
      var store=new WorkflowStateStore(root);
      Assert.Null(store.Begin(id,doc,new RuntimeEvent{Name="ignored",At=start}));
      Assert.Null(store.Begin(id,doc,new RuntimeEvent{Name="piece_damaged",At=start.AddSeconds(31)}));
      Assert.Equal(start.AddSeconds(31),store.Get(id).LastProgressUtc);
      Assert.Null(store.Begin(id,doc,new RuntimeEvent{Name="piece_damaged",At=start.AddSeconds(40)}));
      Assert.Equal(start.AddSeconds(40),store.Get(id).LastProgressUtc);
      var decision=store.Begin(id,doc,new RuntimeEvent{Name="piece_damaged",At=start.AddSeconds(61)});
      Assert.NotNull(decision);
      Assert.Equal(start.AddSeconds(40),decision.EvaluationContext.LastProgressUtc);
    } finally { Directory.Delete(root,true); }
  }
  [Fact] public void DurableTimersSurviveReloadUntilAcknowledged(){var root=Path.Combine(Path.GetTempPath(),"comfy-timer-"+Guid.NewGuid().ToString("N"));try{var id=new WorkflowIdentity{WorldId="w",CharacterId="p",BindingZdo="z",ContentHash="h"};var now=DateTimeOffset.UtcNow;new DurableTimerStore(root).Start(id,"bell",now.AddSeconds(2));Assert.Empty(new DurableTimerStore(root).Due(now));var due=Assert.Single(new DurableTimerStore(root).Due(now.AddSeconds(3)));Assert.Equal("bell",due.TimerId);Assert.Single(new DurableTimerStore(root).Due(now.AddSeconds(4)));Assert.True(new DurableTimerStore(root).Acknowledge(due.Key));Assert.Empty(new DurableTimerStore(root).Due(now.AddSeconds(5)));}finally{Directory.Delete(root,true);}}
  [Fact] public void EngineTimerSignalRequiresStableTimerClause(){var valid=Valid.Replace("\"event\":\"kill\",\"target\":\"Troll\"","\"event\":\"timer_elapsed\",\"where\":{\"timer_id\":\"bell\"}");Assert.True(ExperienceCompiler.CompileJson(valid,new HashSet<string>{"kill"}).IsValid);var invalid=valid.Replace("\"where\":{\"timer_id\":\"bell\"}","\"where\":{}");Assert.Contains(ExperienceCompiler.CompileJson(invalid,new HashSet<string>{"kill"}).Diagnostics,x=>x.Code=="timer.id");}
  [Fact] public void CooperativeChatRequiresClosedActorRole(){var valid=Valid.Replace("\"event\":\"kill\",\"target\":\"Troll\"","\"event\":\"chat_received\",\"target\":\"shout\",\"where\":{\"actor_role\":\"peer\"}");Assert.True(ExperienceCompiler.CompileJson(valid,new HashSet<string>{"kill"}).IsValid);var missing=valid.Replace(",\"where\":{\"actor_role\":\"peer\"}","");Assert.Contains(ExperienceCompiler.CompileJson(missing,new HashSet<string>{"kill"}).Diagnostics,x=>x.Code=="chat.actor_role");var rawIdentity=valid.Replace("\"peer\"","\"123456789\"");Assert.Contains(ExperienceCompiler.CompileJson(rawIdentity,new HashSet<string>{"kill"}).Diagnostics,x=>x.Code=="chat.actor_role");}
  [Fact] public void CooperativeEventsPersistRoleOnly(){Assert.True(CooperativeEventContract.TryCreateInboundChat(22,11,"Shout","secret words",DateTimeOffset.UnixEpoch,out var peer));Assert.Equal("chat_received",peer.Name);Assert.Equal("shout",peer.Target);Assert.Equal("peer",CooperativeEventContract.ActorRole(peer));Assert.Null(peer.SourceId);Assert.DoesNotContain("secret",JsonConvert.SerializeObject(peer));Assert.True(CooperativeEventContract.TryCreateInboundChat(11,11,"Shout","host words",DateTimeOffset.UnixEpoch,out var host));Assert.Equal("listen_host",CooperativeEventContract.ActorRole(host));Assert.False(CooperativeEventContract.TryCreateInboundChat(22,11,"Whisper","private",DateTimeOffset.UnixEpoch,out _));var placed=CooperativeEventContract.CreateHostPlacement("sign(Clone)",DateTimeOffset.UnixEpoch);Assert.Equal("sign",placed.Target);Assert.Equal("listen_host",CooperativeEventContract.ActorRole(placed));}
  [Fact] public void NestedChatWitnessesEmitExactlyOnce(){var dedupe=new CooperativeChatDedupe();Assert.True(dedupe.ShouldEmit(22,"Shout","one","OnNew",10));Assert.False(dedupe.ShouldEmit(22,"Shout","one","RPC",10.1));Assert.True(dedupe.ShouldEmit(22,"Shout","one","OnNew",10.2));Assert.True(dedupe.ShouldEmit(22,"Shout","two","RPC",10.3));}
  [Fact] public void BindingTargetKindsUseClosedRegistry(){var valid=Valid.Replace("\"experience_id\":\"hello\"","\"experience_id\":\"hello\",\"target_kinds\":[\"sign\"]");Assert.True(ExperienceCompiler.CompileJson(valid,new HashSet<string>{"kill"}).IsValid);var invalid=valid.Replace("\"sign\"","\"portal\"");Assert.Contains(ExperienceCompiler.CompileJson(invalid,new HashSet<string>{"kill"}).Diagnostics,x=>x.Code=="binding.target_kind");}
  [Fact] public void MutationActionsUseClosedPrefabAndQuantityRegistry(){var grant=Valid.Replace("{\"id\":\"say\",\"type\":\"message\",\"text\":\"Skal!\"}","{\"id\":\"say\",\"type\":\"grant_item\",\"item\":\"Wood\",\"quantity\":50}");Assert.True(ExperienceCompiler.CompileJson(grant,new HashSet<string>{"kill"}).IsValid);Assert.Contains(ExperienceCompiler.CompileJson(grant.Replace("\"Wood\"","\"SwordCheat\""),new HashSet<string>{"kill"}).Diagnostics,x=>x.Code=="grant_item_not_allowlisted");Assert.Contains(ExperienceCompiler.CompileJson(grant.Replace(":50",":51"),new HashSet<string>{"kill"}).Diagnostics,x=>x.Code=="grant_quantity_exceeds_stack_cap");var spawn=Valid.Replace("{\"id\":\"say\",\"type\":\"message\",\"text\":\"Skal!\"}","{\"id\":\"say\",\"type\":\"spawn\",\"kind\":\"creature\",\"prefab\":\"Greyling\",\"count\":1,\"radius\":3}");Assert.True(ExperienceCompiler.CompileJson(spawn,new HashSet<string>{"kill"}).IsValid);Assert.Contains(ExperienceCompiler.CompileJson(spawn.Replace("\"Greyling\"","\"Troll\""),new HashSet<string>{"kill"}).Diagnostics,x=>x.Code=="spawn_prefab_not_allowlisted");}
  [Fact] public void SpawnLedgerPersistsExactZdoIdentityAndRemovesOnlySelectedRecords(){var root=Path.Combine(Path.GetTempPath(),"comfy-spawn-"+Guid.NewGuid().ToString("N"));try{var store=new SpawnExecutionStore(root);store.Record(new SpawnedObject{ActionKey="owner|stage-one|transition|spawn",ContentHash="h",ActionId="spawn",UserId=7,ObjectId=9});store.Record(new SpawnedObject{ActionKey="other|stage|transition|spawn",ContentHash="h",ActionId="spawn",UserId=7,ObjectId=10});var one=Assert.Single(new SpawnExecutionStore(root).ForOwnerAction("owner","spawn"));Assert.Equal((uint)9,one.ObjectId);new SpawnExecutionStore(root).Remove(new[]{one});Assert.Empty(new SpawnExecutionStore(root).ForOwnerAction("owner","spawn"));Assert.Single(new SpawnExecutionStore(root).ForOwnerAction("other","spawn"));}finally{Directory.Delete(root,true);}}
  static ExperienceDocument TwoStage()=>new(){EntryStage="first",Stages=new(){new(){Id="first",Transitions=new(){new(){Id="first-hit",Priority=10,When=new(){Op="EVENT",Event="piece_damaged"},NextStage="second"}}},new(){Id="second",Transitions=new(){new(){Id="finish",Priority=10,When=new(){Op="EVENT",Event="piece_damaged"},Outcome="complete"}}}}};
  static IEnumerable<TriggerClauseTrace> TraceNodes(TriggerClauseTrace trace){yield return trace;foreach(var child in trace.Children??new())foreach(var nested in TraceNodes(child))yield return nested;}
  static ActiveSet ReadActive(string root)=>JsonConvert.DeserializeObject<ActiveSet>(File.ReadAllText(Path.Combine(root,"active","active-set.json")));
  static string Fixture(string name)=>Path.Combine(AppContext.BaseDirectory,"Fixtures",name);
  static void WritePack(string path,string version,string experience){using var zip=ZipFile.Open(path,ZipArchiveMode.Create);using(var writer=new StreamWriter(zip.CreateEntry("manifest.json").Open()))writer.Write($"{{\"schema\":\"comfy-quest-pack/v2\",\"pack_id\":\"demo\",\"version\":\"{version}\"}}");using(var writer=new StreamWriter(zip.CreateEntry("experiences/demo.json").Open()))writer.Write(experience);}
